import { findOrder } from './db'

export function orderSummary(id: string): string {
  const order = findOrder(id)

  if (!order) {
    return 'Missing order'
  }

  const customerEmail = (order as typeof order & { customerEmail?: string }).customerEmail ?? order.email

  return `${customerEmail} - ${(order.totalCents / 100).toFixed(2)} - ${order.status}`
}

